*{box-sizing:border-box} :root{color-scheme:dark;--ink:#eef3d8;--muted:#a5b39a;--moss:#b7d77a;--deep:#10251f;--line:rgba(222,239,195,.15)}
html,body{margin:0;min-height:100%;background:#0b1c19;color:var(--ink);font-family:'DM Sans',sans-serif}body{display:grid;place-items:center;overflow-x:hidden;background:radial-gradient(ellipse at 50% 20%,#19352b 0,#0e211d 46%,#091714 100%)}button{font:inherit;color:inherit}.game-shell{width:min(1200px,100%);padding:20px 34px 16px}.topbar{height:48px;display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.brand{display:flex;align-items:center;gap:9px;color:#e3edcc;text-decoration:none;font-weight:800;font-size:12px;letter-spacing:.18em}.brand-mark{display:grid;place-items:center;color:#c5e488;font-size:21px}.top-note,.sound-toggle,.footer{font-family:'DM Mono',monospace;font-size:9px;letter-spacing:.1em;color:#96a998}.top-note{display:flex;align-items:center;gap:9px}.live-dot{height:6px;width:6px;background:#b8d985;border-radius:50%;box-shadow:0 0 11px #b8d985}.separator{color:#597365}.sound-toggle{border:1px solid var(--line);background:rgba(220,240,205,.035);padding:8px 12px;border-radius:20px;cursor:pointer;display:flex;gap:7px;align-items:center}.sound-toggle:hover{border-color:#b8d985;color:#d7e9c2}.sound-icon{font-size:15px;color:#c4df91}.game-frame{position:relative;width:100%;aspect-ratio:16/9;min-height:300px;overflow:hidden;border:1px solid rgba(198,221,167,.22);border-radius:8px;background:#142b25;box-shadow:0 25px 80px #050d0b99,0 0 0 5px #dce8c007}.game-frame canvas{display:block;width:100%;height:100%;image-rendering:auto}.hud{position:absolute;inset:0 0 auto;z-index:2;display:flex;align-items:flex-start;padding:21px 24px;pointer-events:none;background:linear-gradient(180deg,rgba(8,24,21,.58),transparent)}.hud[hidden],.boss-hud[hidden],.touch-controls[hidden]{display:none}.hud-left{display:flex;gap:22px;align-items:center}.health-card,.coin-card{min-height:42px}.hud-label,.stage-kicker,.boss-heading{font:9px 'DM Mono',monospace;letter-spacing:.15em;color:#d3dec1}.leaves{display:flex;gap:4px;padding-top:5px}.leaf{font-size:19px;color:#bad97b;text-shadow:0 0 12px #9aca5d;transition:.2s}.leaf.empty{color:#617362;text-shadow:none;opacity:.62}.coin-card{display:flex;align-items:center;gap:5px;font:14px 'DM Mono',monospace;color:#f3e7ae}.coin-glyph{color:#f4d56b;font-size:17px;text-shadow:0 0 12px #e4ba50}.coin-label{font-size:8px;color:#d7dfca;letter-spacing:.13em;margin-left:4px}.stage-card{margin:auto;display:flex;flex-direction:column;align-items:center;gap:4px}.stage-kicker{font-size:8px}.stage-kicker b{color:#d7ebaa}.stage-name{font-family:Fraunces,serif;font-size:18px;text-shadow:0 2px 10px #08130f}.pause-button{pointer-events:auto;background:rgba(9,24,20,.48);border:1px solid #dfe9d044;border-radius:50%;height:34px;width:34px;color:#e3edcf;cursor:pointer;font-size:12px}.boss-hud{position:absolute;z-index:2;bottom:22px;left:50%;transform:translateX(-50%);width:min(340px,50%);padding:10px 13px;background:#10251fc9;border:1px solid #dce8c033;border-radius:5px;backdrop-filter:blur(8px)}.boss-heading{display:flex;justify-content:space-between;font-size:8px;margin-bottom:7px}.boss-heading span:last-child{color:#d7e99d}.boss-track{height:5px;background:#526258;border-radius:5px;overflow:hidden}.boss-track div{height:100%;width:100%;background:linear-gradient(90deg,#d9bc72,#e88b64);transition:width .25s}.toast{position:absolute;z-index:3;top:24%;left:50%;transform:translate(-50%,-10px);opacity:0;pointer-events:none;padding:9px 16px;background:#12271edb;border:1px solid #d7e9a74c;border-radius:20px;font:10px 'DM Mono',monospace;letter-spacing:.08em;color:#e9efce;transition:.22s}.toast.show{opacity:1;transform:translate(-50%,0)}.screen{position:absolute;inset:0;z-index:4;display:grid;place-items:center;background:linear-gradient(90deg,rgba(7,19,17,.6),rgba(7,19,17,.17) 58%,rgba(7,19,17,.28));}.screen:empty{display:none}.screen-card{width:min(430px,88%);padding:28px 34px 24px;background:rgba(11,28,24,.86);border:1px solid rgba(219,237,192,.25);border-radius:8px;box-shadow:0 18px 50px #06120f70;backdrop-filter:blur(12px);text-align:left;animation:arrive .4s ease-out}@keyframes arrive{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}.title-card{margin-left:3%;}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:.16em;color:#bdd88d}.tiny-star{color:#f0d47a;font-size:12px;margin-right:5px}.screen h1{font:800 clamp(44px,7vw,68px)/.95 Fraunces,serif;letter-spacing:-.055em;color:#f0f3db;margin:15px 0 5px}.screen h1 span{color:#c4df8b}.subtitle{font:italic 17px Fraunces,serif;color:#d4e5ac;margin:0 0 18px}.intro{font-size:12px;line-height:1.75;color:#b9c9b7;margin:0 0 21px}.primary-button{display:flex;justify-content:space-between;align-items:center;width:100%;padding:13px 15px;border:0;border-radius:4px;background:#c5dc8e;color:#17291f;font-size:10px;font-weight:800;letter-spacing:.12em;cursor:pointer;transition:background .16s,transform .16s}.primary-button span{font-size:16px}.primary-button:hover{background:#d9ecaa;transform:translateY(-1px)}.control-hint{margin-top:16px;text-align:center;font:8px 'DM Mono',monospace;letter-spacing:.09em;color:#a9baa4}.control-hint span{color:#e0e9ce}.control-hint i{font-style:normal;color:#637a6b;margin:0 4px}.controller-hint{font:8px 'DM Mono',monospace;text-align:center;color:#829886;margin-top:12px}.controller-hint span{color:#c4db8b;margin:0 5px}.shop-card{width:min(500px,90%)}.screen h2{font:700 29px/1.1 Fraunces,serif;letter-spacing:-.035em;margin:10px 0 12px}.shop-balance{font:11px 'DM Mono',monospace;color:#b4c5b0;margin:0 0 13px}.shop-balance b{color:#f0d77f;margin-left:7px}.upgrade-list{display:grid;gap:7px;margin-bottom:15px}.upgrade{width:100%;display:flex;align-items:center;gap:12px;padding:10px 11px;text-align:left;background:#e4edcf0a;border:1px solid #dfe9d025;border-radius:4px;cursor:pointer;transition:.16s}.upgrade:hover{background:#c9df8b16;border-color:#c9df8b72}.upgrade:disabled{opacity:.42;cursor:default}.upgrade-icon{width:30px;height:30px;display:grid;place-items:center;border-radius:50%;background:#d9e8ba16;color:#d0e79c;font-size:18px}.upgrade span:nth-child(2){flex:1;display:grid;gap:3px}.upgrade b{font-size:11px;color:#e4edd8}.upgrade small{font-size:9px;color:#95a995}.upgrade strong{font:10px 'DM Mono',monospace;color:#f0d77f}.end-card{text-align:center}.end-card .intro{margin-bottom:14px}.end-stats{font:9px 'DM Mono',monospace;color:#bacbb1;margin:8px 0 18px}.pause-card{text-align:center;width:min(350px,88%)}.pause-card .intro{margin-bottom:14px}.footer{display:flex;justify-content:space-between;align-items:center;padding:13px 2px 0;font-size:8px;letter-spacing:.12em}.footer span:first-child{color:#9eaf9d}.footer b{font-weight:400;color:#d7e3c9;border:1px solid #c9dbc333;border-radius:3px;padding:2px 4px}.touch-controls{position:absolute;inset:auto 0 12px;z-index:3;display:flex;justify-content:space-between;padding:0 18px;pointer-events:none}.touch-move,.touch-actions{display:flex;align-items:flex-end;gap:9px;pointer-events:auto}.touch-controls button{border:1px solid #e8f2d85c;background:#10261fad;color:#eff4df;border-radius:50%;width:53px;height:53px;font-size:26px;touch-action:none;user-select:none;box-shadow:0 3px 12px #06110e66}.touch-controls .touch-attack{width:46px;height:46px;color:#f2d87c}.touch-controls .touch-jump{color:#d0e99a}.touch-controls button:active,.touch-controls button.active{background:#b4d77a;color:#14251c;transform:scale(.94)}
@media(max-width:700px){.game-shell{padding:10px 9px}.topbar{height:34px;margin-bottom:8px}.brand{font-size:10px}.top-note{display:none}.sound-toggle{font-size:8px;padding:6px 9px}.game-frame{min-height:0;border-radius:5px;aspect-ratio:16/10}.hud{padding:12px 12px}.hud-left{gap:10px}.hud-label,.stage-kicker{font-size:7px}.leaf{font-size:15px}.coin-card{font-size:11px}.coin-label{font-size:7px}.stage-name{font-size:13px}.pause-button{width:28px;height:28px}.screen-card{padding:20px 21px 17px}.screen h1{font-size:47px}.subtitle{font-size:14px}.intro{font-size:10px}.primary-button{padding:11px 12px;font-size:9px}.control-hint{font-size:7px}.controller-hint{font-size:7px}.footer{font-size:6px;letter-spacing:.05em}.footer span:last-child{display:none}.boss-hud{bottom:68px;width:55%}.touch-controls{bottom:8px;padding:0 9px}.touch-controls button{height:45px;width:45px;font-size:22px}.touch-controls .touch-attack{height:40px;width:40px}}
@media(max-width:430px){.game-frame{aspect-ratio:4/3}.screen-card{padding:15px 16px}.title-card{margin:0}.screen h1{font-size:42px;margin-top:9px}.subtitle{margin-bottom:11px}.intro{line-height:1.55;margin-bottom:13px}.control-hint{margin-top:10px}.controller-hint{margin-top:7px}.upgrade{padding:7px}.upgrade-icon{width:25px;height:25px}}

(() => {
  'use strict';

  // Mosslight is a small, asset-free canvas platformer. World coordinates stay
  // independent of the canvas size; the renderer scales to desktop and phones.
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const screen = document.querySelector('#screen');
  const titleCard = document.querySelector('#titleCard');
  const shopCard = document.querySelector('#shopCard');
  const endCard = document.querySelector('#endCard');
  const pauseCard = document.querySelector('#pauseCard');
  const hud = document.querySelector('#hud');
  const bossHud = document.querySelector('#bossHud');
  const touchControls = document.querySelector('#touchControls');
  const W = 960, H = 540, FLOOR = 454, GRAVITY = 1750;
  const stageNames = ['Fernfall Trail', 'The Gloaming Wilds'];
  const keys = new Set();
  const touch = { left:false, right:false, jump:false, attack:false };
  let gameMode = 'title', lastTime = 0, cameraX = 0, elapsed = 0;
  let player, platforms, enemies, coins, particles, bolts, webs, boss, worldWidth;
  let stage = 0, checkpointX = 80, totalSeeds = 0, audioOn = true, audioCtx;
  let toastTimer = 0, screenShake = 0, bossDefeated = false, deaths = 0;
  const upgrades = { double:false, damage:1, health:5 };

  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const rand = (a,b) => a + Math.random() * (b-a);
  const rects = (a,b) => a.x < b.x+b.w && a.x+a.w > b.x && a.y < b.y+b.h && a.y+a.h > b.y;
  const roundRect = (c,x,y,w,h,r) => { c.beginPath(); c.roundRect(x,y,w,h,r); };

  function resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = W * dpr; canvas.height = H * dpr;
    ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  window.addEventListener('resize', resize); resize();

  function sound(freq=440, duration=.08, type='sine', volume=.035) {
    if (!audioOn) return;
    try {
      audioCtx ||= new (window.AudioContext || window.webkitAudioContext)();
      const o=audioCtx.createOscillator(), g=audioCtx.createGain();
      o.type=type; o.frequency.setValueAtTime(freq,audioCtx.currentTime);
      if(type==='sine') o.frequency.exponentialRampToValueAtTime(Math.max(50,freq*.72),audioCtx.currentTime+duration);
      g.gain.setValueAtTime(volume,audioCtx.currentTime); g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);
      o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);
    } catch(_) {}
  }
  function showToast(message) {
    const el=document.querySelector('#toast'); el.textContent=message;el.classList.add('show');toastTimer=2.1;
  }
  function setScreen(which) {
    screen.replaceChildren();
    const card={title:titleCard,shop:shopCard,end:endCard,pause:pauseCard}[which];
    if(card){card.hidden=false;screen.appendChild(card);}
    gameMode=which;
    hud.hidden=which==='title'||which==='end';
    touchControls.hidden=which!=='playing'||!isTouchDevice();
    if(which!=='playing') bossHud.hidden=true;
  }
  const isTouchDevice=()=>('ontouchstart' in window)||navigator.maxTouchPoints>0;

  function makePlayer(x=80) {
    return {x,y:FLOOR-48,w:32,h:48,vx:0,vy:0,face:1,onGround:false,jumps:0,
      hp:upgrades.health,maxHp:upgrades.health,invuln:0,attackCd:0,flash:0,anim:0};
  }
  function setupStage(index, preservePlayer=false) {
    stage=index; worldWidth=3300;
    platforms=[
      {x:270,y:390,w:120,h:18},{x:520,y:340,w:124,h:18},{x:770,y:390,w:155,h:18},
      {x:1050,y:350,w:135,h:18},{x:1320,y:395,w:160,h:18},{x:1580,y:340,w:150,h:18},
      {x:1880,y:385,w:140,h:18},{x:2130,y:330,w:150,h:18},{x:2420,y:390,w:165,h:18}
    ];
    if(index===1) platforms.push({x:930,y:320,w:135,h:18},{x:1740,y:300,w:150,h:18},{x:2250,y:275,w:135,h:18});
    const count=index===0?8:10;
    enemies=Array.from({length:count},(_,i)=>({x:420+i*310+(i%2)*45,y:FLOOR-32,w:34,h:32,baseX:360+i*310,range:125,dir:i%2?1:-1,speed:45+index*8,alive:true,anim:rand(0,8)}));
    coins=[];
    for(let i=0;i<17;i++) coins.push({x:190+i*175,y:FLOOR-58-(i%3)*25,r:9,taken:false,bob:rand(0,6)});
    for(const p of platforms) for(let j=0;j<2;j++) coins.push({x:p.x+38+j*46,y:p.y-20,r:8,taken:false,bob:rand(0,6)});
    particles=[];bolts=[];webs=[];boss={x:worldWidth-370,y:FLOOR-138,w:118,h:112,hp:index===0?7:10,maxHp:index===0?7:10,timer:1.6,state:'idle',attackTimer:2,flash:0};
    bossDefeated=false;checkpointX=80;cameraX=0;
    if(!preservePlayer||!player) player=makePlayer(80);
    else {player.x=80;player.y=FLOOR-player.h;player.vx=player.vy=0;player.hp=player.maxHp;player.invuln=1.2;player.jumps=0;}
    document.querySelector('#stageNumber').textContent=String(index+1).padStart(2,'0');
    document.querySelector('#stageName').textContent=stageNames[index];
    bossHud.hidden=true;
    updateHud();
  }

  function startGame() {
    totalSeeds=0;deaths=0;upgrades.double=false;upgrades.damage=1;upgrades.health=5;
    player=null;setupStage(0);setScreen('playing');sound(620,.14,'sine');
  }
  function updateHud() {
    if(!player)return;
    const leaves=document.querySelector('#leaves');leaves.replaceChildren();
    for(let i=0;i<player.maxHp;i++){const leaf=document.createElement('span');leaf.className='leaf'+(i>=player.hp?' empty':'');leaf.textContent='❧';leaves.appendChild(leaf);}
    document.querySelector('#coinCount').textContent=String(totalSeeds).padStart(2,'0');
    if(boss){document.querySelector('#bossHealth').style.width=`${Math.max(0,boss.hp/boss.maxHp*100)}%`;}
  }

  function inputState() {
    let left=keys.has('ArrowLeft')||keys.has('KeyA')||touch.left;
    let right=keys.has('ArrowRight')||keys.has('KeyD')||touch.right;
    let jump=keys.has('Space')||keys.has('ArrowUp')||keys.has('KeyW')||keys.has('KeyZ')||touch.jump;
    let attack=keys.has('KeyX')||keys.has('KeyJ')||keys.has('KeyK')||touch.attack;
    const pads=navigator.getGamepads?.()||[];const pad=Array.from(pads).find(Boolean);
    if(pad){left||=pad.axes[0]<-.28||pad.buttons[14]?.pressed;right||=pad.axes[0]>.28||pad.buttons[15]?.pressed;jump||=!!pad.buttons[0]?.pressed||!!pad.buttons[12]?.pressed;attack||=!!pad.buttons[2]?.pressed||!!pad.buttons[5]?.pressed;}
    return {left,right,jump,attack};
  }
  let jumpWasDown=false,attackWasDown=false;
  function doJump() {
    if(player.onGround||upgrades.double&&player.jumps<2){player.vy=player.jumps? -565:-610;player.onGround=false;player.jumps++;sound(player.jumps>1?460:560,.11,'triangle');burst(player.x+player.w/2,player.y+player.h,'#d7e8a5',7);}
  }
  function attack() {
    if(player.attackCd>0)return;
    player.attackCd=.36;player.flash=.16;
    bolts.push({x:player.x+(player.face>0?player.w:-10),y:player.y+20,w:16,h:11,vx:player.face*570,life:1.15,damage:upgrades.damage});
    sound(700,.1,'triangle',.022);burst(player.x+player.w/2+player.face*20,player.y+23,'#d6ec92',4);
  }

input.newString:
  sound(700,.1,'triangle',.022);burst(player.x+player.w/2+player.face*20,player.y+23,'#d6ec92',4);
}

function burst(x,y,color,n=8) {
  for(let i=0;i<n;i++) particles.push({x,y,vx:rand(-115,115),vy:rand(-175,25),life:rand(.3,.72),max:.72,color,r:rand(2,4)});
}
function damagePlayer() {
  if(player.invuln>0)return;
  player.hp--;player.invuln=1.35;player.vy=-330;player.vx=-player.face*190;screenShake=8;
  sound(145,.22,'sawtooth',.045);burst(player.x+player.w/2,player.y+22,'#f1a37c',12);updateHud();
  if(player.hp<=0){
    deaths++;totalSeeds=0;showToast('THE WOOD GIVES YOU ANOTHER CHANCE');
    player.x=checkpointX;player.y=FLOOR-player.h;player.vx=player.vy=0;player.hp=player.maxHp;player.invuln=2;
    if(bossDefeated===false&&boss.x<worldWidth-350)boss.hp=boss.maxHp;
    cameraX=Math.max(0,player.x-300);updateHud();
  }
}
function hitEnemy(enemy) {
  enemy.alive=false;for(let i=0;i<3;i++)coins.push({x:enemy.x+rand(2,enemy.w-2),y:enemy.y-5,r:8,taken:false,bob:rand(0,6)});
  burst(enemy.x+enemy.w/2,enemy.y+10,'#c7df83',12);sound(270,.12,'square',.025);showToast('A LITTLE LIGHT LEFT BEHIND');
}
function update(dt) {
  elapsed+=dt; if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.querySelector('#toast').classList.remove('show');}
  if(screenShake>0)screenShake=Math.max(0,screenShake-dt*28);
  if(gameMode!=='playing')return;
  const input=inputState();
  if(input.jump&&!jumpWasDown)doJump();
  if(input.attack&&!attackWasDown)attack();
  jumpWasDown=input.jump;attackWasDown=input.attack;
  const speed=245, accel=1900;
  if(input.left){player.vx=Math.max(player.vx-accel*dt,-speed);player.face=-1;}
  else if(input.right){player.vx=Math.min(player.vx+accel*dt,speed);player.face=1;}
  else player.vx*=Math.pow(.001,dt);
  if(!input.jump&&player.vy< -170)player.vy+=GRAVITY*dt*1.35; // variable-height jump
  player.vy=Math.min(player.vy+GRAVITY*dt,980);
  player.x=clamp(player.x+player.vx*dt,0,worldWidth-player.w);
  const oldY=player.y;player.y+=player.vy*dt;player.onGround=false;
  if(player.y+player.h>=FLOOR){player.y=FLOOR-player.h;player.vy=0;player.onGround=true;player.jumps=0;}
  for(const p of platforms){
    if(player.x+player.w>p.x&&player.x<p.x+p.w&&oldY+player.h<=p.y+4&&player.y+player.h>=p.y&&player.vy>=0){player.y=p.y-player.h;player.vy=0;player.onGround=true;player.jumps=0;}
  }
  player.anim+=dt*Math.abs(player.vx)*.045;player.invuln=Math.max(0,player.invuln-dt);player.attackCd=Math.max(0,player.attackCd-dt);player.flash=Math.max(0,player.flash-dt);
  if(player.y>H+250){damagePlayer();player.y=FLOOR-player.h;}
  if(player.x>checkpointX+620){checkpointX=Math.floor(player.x/600)*600;showToast('TRAIL MARKER FOUND');}

  for(const e of enemies){if(!e.alive)continue;e.anim+=dt*e.speed*.07;e.x+=e.dir*e.speed*dt;if(e.x<e.baseX-e.range||e.x>e.baseX+e.range)e.dir*=-1;
    if(rects(player,e)){
      if(player.vy>40&&oldY+player.h<e.y+12){player.y=e.y-player.h;player.vy=-410;player.jumps=0;hitEnemy(e);}
      else if(player.invuln<=0)damagePlayer();
    }
  }
  for(const c of coins){c.bob+=dt*3;if(!c.taken&&rects(player,{x:c.x-c.r,y:c.y-c.r+Math.sin(c.bob)*3,w:c.r*2,h:c.r*2})){c.taken=true;totalSeeds++;sound(850+Math.min(totalSeeds,15)*24,.07,'sine',.025);burst(c.x,c.y,'#f1d978',5);updateHud();}}
  for(const b of bolts){b.x+=b.vx*dt;b.life-=dt;
    for(const e of enemies)if(e.alive&&rects(b,e)){hitEnemy(e);b.life=0;break;}
    if(!bossDefeated&&boss.state==='open'&&rects(b,{x:boss.x+42,y:boss.y+12,w:38,h:38})){boss.hp-=b.damage;boss.flash=.2;b.life=0;burst(boss.x+61,boss.y+30,'#f4db84',10);sound(390,.14,'triangle',.04);screenShake=4;if(boss.hp<=0)defeatBoss();updateHud();}
    else if(!bossDefeated&&rects(b,boss)&&boss.state!=='open'){b.life=0;burst(b.x,b.y,'#91aa96',3);}
  }
  bolts=bolts.filter(b=>b.life>0&&b.x>-30&&b.x<worldWidth+30);
  updateBoss(dt);
  for(const w of webs){w.x+=w.vx*dt;w.y+=w.vy*dt;w.vy+=160*dt;w.life-=dt;if(rects(w,player)&&player.invuln<=0){damagePlayer();w.life=0;} }
  webs=webs.filter(w=>w.life>0&&w.x>-50&&w.x<worldWidth+50);
  for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=420*dt;p.life-=dt;}
  particles=particles.filter(p=>p.life>0);
  if(!bossDefeated&&player.x>boss.x-430)bossHud.hidden=false;
  if(!bossDefeated&&player.x>boss.x+boss.w+35){player.x=boss.x-80;player.vx=0;showToast('THE WEB BLOCKS YOUR WAY');}
  cameraX=clamp(player.x-W*.38,0,worldWidth-W);
  updateHud();
}
function updateBoss(dt) {
  if(bossDefeated)return;
  boss.timer-=dt;boss.attackTimer-=dt;boss.flash=Math.max(0,boss.flash-dt);
  if(boss.timer<=0){
    if(boss.state==='idle'){boss.state='open';boss.timer=1.45;document.querySelector('#bossState').textContent='WEAK SPOT EXPOSED';sound(520,.18,'sine',.025);}
    else {boss.state='idle';boss.timer=3.0;document.querySelector('#bossState').textContent='LISTENING…';}
